__NUXT_JSONP__("/inclusion/noticias/en_el_olvido_miles_de_trabajadoras_agricolas_expuestas_a_plaguicidas_y_deshidratacion_pero_sin_imss", (function(a,b,c,d){return {data:[{post:{slug:"en_el_olvido_miles_de_trabajadoras_agricolas_expuestas_a_plaguicidas_y_deshidratacion_pero_sin_imss",title:"En el olvido miles de trabajadoras agrícolas; expuestas a plaguicidas y deshidratación pero sin IMSS",date:"2025-09-26T19:13:27.716Z",img:"https:\u002F\u002Fucarecdn.com\u002F059d4619-5e0f-4c95-bcef-7600deee3f82\u002F","img-alt":"Jornaleras agrícolas",autor:"Alejandro Páez, La Crónica",link:"https:\u002F\u002Fwww.cronica.com.mx\u002Fnacional\u002F2025\u002F09\u002F25\u002Fen-el-olvido-miles-de-trabajadoras-agricolas-expuestas-a-plaguicidas-y-deshidratacion-pero-sin-imss\u002F",category:"inclusion",extracto:"La proporción de accidentes de trabajo reportados al IMSS de jornaleras agrícolas pasó del 6% en 2000 al 35% en 2024, según el informe de política pública “Sembrando el cambio: Hacia un futuro justo para las trabajadoras agrícolas en México”.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"Son las que sostienen la seguridad alimentaria del país, pero las mujeres jornaleras sufren una sistemática violación de sus derechos laborales a tal grado que 9 de cada 10 no cuentan con IMSS ni seguridad social a pesar de que son las que están más expuestas a mayores accidentes laborales que ponen en riesgo su vida debido a la exposición a plaguicidas, los golpes de calor o la deshidratación., según la Organización Internacional del Trabajo."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El organismo estima que, a nivel global, 270 mil personas jornaleras agrícolas mueren al año por accidentes laborales."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"La proporción de accidentes de trabajo reportados al IMSS de jornaleras agrícolas pasó del 6% en 2000 al 35% en 2024, según el informe de política pública “Sembrando el cambio: Hacia un futuro justo para las trabajadoras agrícolas en México”, financiado por la Unión Europea y y realizado por Fundación Avina, Oxfam México, Fundación Ethos y Proyecto de Derechos Económicos, Sociales y Culturales (ProDESC)."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Las trabajadoras agrícolas son fundamentales para la economía y la seguridad alimentaria del país. Sin embargo, la corrupción, la violación de los derechos laborales y la falta de acción efectiva del Estado mantienen a cientos de miles de mujeres en condiciones de vulnerabilidad extrema”, advierte."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El documento recuerda que por ley todas las personas trabajadoras agrícolas o jornaleras deben estar afiliadas al IMSS."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Sin embargo, las empresas agrícolas utilizan mecanismos corruptos y fraudulentos a fin de evitar el registro formal de sus trabajadoras y optando por generar “pases” (se proporciona atención médica eventual sin generar derechos) en caso de accidentes laborales, pero lo más grave es que eso imposibilita el acceso a una pensión."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"La investigación también detalla que alrededor del 90% de las jornaleras agrícolas carece de contrato formal. Sumado a ello, existe una falta de inspectores federales pues solo hay 660 inspectores para más de 456 mil centros de trabajo registrados en todo el país, lo que prácticamente deja sin vigilancia a estas empresas y con ello se perpetúa la violación de los derechos laborales de estas trabajadoras."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"SIN GUARDERÍAS"}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Pero eso no es todo, pues las condiciones para las jornaleras agrícolas se complica aún más porque de manera gradual, el gobierno federal ha cancelado “las guarderías de campo” del IMSS., con lo cual estas mujeres no tienen donde dejar a sus hijos o bien se los llevan al trabajo con lo que los menores se ponen en riesgo o bien se fomenta el trabajo infantil."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En la última década, se redujeron las “guarderías de campo” del IMSS un 50%, pasando de 13 en 2012 a 6 para 2024, además de un recorte presupuestal del 37% para este servicio. lo que obliga a las jornaleras agrícolas a vivir una sobrecarga de cuidados, a abandonar sus empleos o incluso a llevar a sus hijos e hijas a sus centros de trabajo, lo que aumenta el riesgo de accidentes, propicia el trabajo infantil y agudiza el rezago y la deserción escolar."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El incumplimiento de los derechos laborales para las jornaleras agrícolas se posibilita por la inacción gubernamental pues existe una ambigüedad institucional respecto al nivel de gobierno que debe supervisar dicho cumplimiento."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"A ello se suma la falta de inspectores federales, únicamente 660 inspectores deben supervisar más de 456 mil centros de trabajo registrados en todo el país, lo que agrava el problema y dificulta la capacidad del estado de proteger y garantizar derechos humanos y trabajo digno."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El informe de política pública “Sembrando el cambio: Hacia un futuro justo para las trabajadoras agrícolas en México” propone que se garantice el cumplimiento de la ley mediante una vigilancia efectiva y transparente que fortalezca la inspección con perspectiva de género."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Se asegure la afiliación real al IMSS de las trabajadoras y se erradiquen los mecanismos informales de acceso a la salud (“pases”), se amplíen y adapten los servicios de guardería para las familias agrícolas."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Además es necesario que se implementen protocolos contra la violencia y discriminación de las mujeres trabajadoras agrícolas."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Fen_el_olvido_miles_de_trabajadoras_agricolas_expuestas_a_plaguicidas_y_deshidratacion_pero_sin_imss",extension:".md",createdAt:"2025-11-25T01:24:03.263Z",updatedAt:"2025-11-25T01:24:03.264Z"}}],fetch:{},mutations:[]}}("text","element","p","\n")));